css:
.mdilemma-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2733;
    background: linear-gradient(160deg, #eef1f6 0%, #e4e8f0 100%);
    border-radius: 18px;
}

.mdilemma-container * {
    box-sizing: border-box;
}

.mdilemma-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1b2a44 0%, #243a5e 55%, #324f7d 100%);
    color: #f3f6fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(27, 42, 68, 0.32);
}

.mdilemma-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.mdilemma-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #f0c98a;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.mdilemma-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dce4f0;
}

.mdilemma-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2b3a55;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.mdilemma-period-counter #currentDay,
.mdilemma-period-counter #maxPeriods {
    font-weight: 800;
    color: #1b2a44;
}

.mdilemma-round-name {
    background: #d8e0ee;
    color: #1b2a44;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.mdilemma-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a2d1f;
    background: #f8e0da;
    padding: 4px 12px;
    border-radius: 999px;
}

.mdilemma-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.mdilemma-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d9dfeb;
    box-shadow: 0 4px 14px rgba(27, 42, 68, 0.06);
    border-top: 4px solid #324f7d;
}

.mdilemma-card-trust { border-top-color: #1d6f5b; }
.mdilemma-card-ethics { border-top-color: #5a4aa8; }
.mdilemma-card-deadline { border-top-color: #2f6fb0; }
.mdilemma-card-cred { border-top-color: #c08416; }

.mdilemma-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7689;
}

.mdilemma-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1b2a44;
}

.mdilemma-card-trust .mdilemma-value { color: #1d6f5b; }
.mdilemma-card-ethics .mdilemma-value { color: #5a4aa8; }
.mdilemma-card-deadline .mdilemma-value { color: #2f6fb0; }
.mdilemma-card-cred .mdilemma-value { color: #c08416; }

.mdilemma-sublabel {
    font-size: 0.76rem;
    color: #7a869a;
    line-height: 1.35;
}

.mdilemma-trust-strong .mdilemma-value { color: #1d6f5b; }
.mdilemma-trust-low .mdilemma-value { color: #c0392b; }

.mdilemma-deadline-safe .mdilemma-value { color: #1d6f5b; }
.mdilemma-deadline-risk .mdilemma-value { color: #c0392b; }

.mdilemma-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1b2a44;
    color: #eaf0f8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.mdilemma-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0c98a;
}

.mdilemma-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #324f7d;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(27, 42, 68, 0.05);
}

.mdilemma-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.mdilemma-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1b2a44;
    margin-bottom: 6px;
}

.mdilemma-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #344256;
}

.mdilemma-briefing-text strong { color: #1d6f5b; }
.mdilemma-briefing-text em { color: #9a2d1f; font-style: italic; }

.mdilemma-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d9dfeb;
    box-shadow: 0 4px 14px rgba(27, 42, 68, 0.06);
}

.mdilemma-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1b2a44;
    border-bottom: 2px solid #e4e8f0;
    padding-bottom: 8px;
}

.mdilemma-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #283750;
    margin: 14px 0 6px;
}

.mdilemma-container select,
.mdilemma-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c2cbdc;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7f9fc;
    color: #1f2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.mdilemma-container select:focus,
.mdilemma-container input[type="number"]:focus {
    outline: none;
    border-color: #324f7d;
    box-shadow: 0 0 0 3px rgba(50, 79, 125, 0.16);
}

.mdilemma-container select option {
    background-color: #ffffff;
    color: #1f2733;
}

.mdilemma-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #324f7d;
}

.mdilemma-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2b3a55;
    margin-top: 4px;
}

.mdilemma-range-readout span:last-child {
    color: #1d6f5b;
    font-weight: 800;
}

.mdilemma-hint {
    font-size: 0.8rem;
    color: #7a869a;
    margin-top: 4px;
    line-height: 1.4;
}

.mdilemma-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.mdilemma-container .btn-primary {
    background: linear-gradient(135deg, #1d6f5b 0%, #324f7d 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(29, 111, 91, 0.28);
}

.mdilemma-container .btn-primary:hover {
    filter: brightness(1.07);
}

.mdilemma-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c2cbdc;
    color: #6a7689;
}

.mdilemma-coach {
    background: #1b2a44;
    color: #eaf0f8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(27, 42, 68, 0.22);
}

.mdilemma-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fb0d8;
    margin-bottom: 8px;
}

.mdilemma-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.mdilemma-coach-body strong { color: #f0c98a; }
.mdilemma-coach-body em { color: #f3b6a6; font-style: italic; }

.mdilemma-history,
.mdilemma-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d9dfeb;
    box-shadow: 0 4px 14px rgba(27, 42, 68, 0.06);
}

.mdilemma-history h3,
.mdilemma-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1b2a44;
}

.mdilemma-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #283750;
}

.mdilemma-container table#usfHistoryTable th {
    background: #eef1f7;
    color: #1b2a44;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6deea;
}

.mdilemma-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f6;
}

.mdilemma-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafc;
}

.mdilemma-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .mdilemma-container {
        padding: 14px;
    }
    .mdilemma-header h1 {
        font-size: 1.7rem;
    }
    .mdilemma-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .mdilemma-value {
        font-size: 2rem;
    }
    .mdilemma-clock {
        margin-left: 0;
    }
    .mdilemma-period-counter {
        font-size: 0.88rem;
    }
    .mdilemma-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .mdilemma-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) */
.mdilemma-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1b2a44; }
.mdilemma-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(27,42,68,0.14); margin-bottom: 16px; }
.mdilemma-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1d6f5b; }
.mdilemma-cm-score-max { font-size: 18px; font-weight: 600; color: #324f7d; margin-left: 2px; }
.mdilemma-cm-grade { font-size: 18px; font-weight: 700; color: #1b2a44; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.mdilemma-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.mdilemma-cm-yes { background: rgba(29,111,91,0.15); color: #155543; }
.mdilemma-cm-no { background: rgba(192,57,43,0.12); color: #b03325; }
.mdilemma-cm-warn { background: rgba(180,120,20,0.16); color: #8a5c10; }
.mdilemma-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.mdilemma-cm-metric { flex: 1 1 110px; background: #eef1f7; border: 1px solid rgba(27,42,68,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.mdilemma-cm-mv { display: block; font-size: 24px; font-weight: 800; color: #1b2a44; }
.mdilemma-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #324f7d; margin-top: 2px; }
.mdilemma-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #324f7d; margin-bottom: 8px; }
.mdilemma-cm-insights { margin: 0; padding-left: 20px; }
.mdilemma-cm-insights li { font-size: 14px; line-height: 1.5; color: #2b3a52; margin-bottom: 8px; }

