(function() {
    'use strict';

    class DilemmaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Manager's Dilemma`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (GBP).
            this.AURORA_BILLINGS = 1.9;     // £1.9M / year
            this.SERVICE_CREDIT = 0.095;    // £95k = 5% milestone credit
            this.RENEWAL_AT_RISK = 5.7;     // £5.7M / 3 years
            this.ATTRITION_COST = 0.6;      // ~£600k if 2 senior engineers leave
            this.MAX_EXPOSURE = 6.4;        // £6.4M ≈ credit + attrition + renewal at risk

            // Starting KPIs — deliberately low (the team is watching, the promotion is "a stretch"),
            // with headroom so every wrong lever still registers through round 4.
            this.START_TRUST = 42;
            this.START_ETHICS = 50;
            this.START_DEADLINE = 45;
            this.START_CRED = 40;

            // Concept "correct" answers.
            this.RIGHT_READ = `read`;
            this.RIGHT_CLASH = `candourcare`;
            this.RIGHT_METHOD = `full`;
            this.RIGHT_AISHA = `thirdway`;
            this.RIGHT_TOM = `caretruth`;
            this.RIGHT_DISCLOSE = `sequenced`;
            this.RIGHT_DEFEND = `eiethics`;
            this.RIGHT_PRECEDENT = `fairtough`;
            this.RIGHT_THIRTY = `concrete`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: this.START_TRUST,
                    ethics: this.START_ETHICS,
                    deadline: this.START_DEADLINE,
                    cred: this.START_CRED,
                    exposure: this.MAX_EXPOSURE,
                    complicit: false,
                    deadlineMissed: false,
                    trustHistory: [this.START_TRUST],
                    ethicsHistory: [this.START_ETHICS],
                    deadlineHistory: [this.START_DEADLINE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    read: `read`,
                    clash: `candourcare`,
                    link: 50,
                    method: `full`,
                    thirdAisha: `thirdway`,
                    options: 3,
                    publicity: 60,
                    tom: `caretruth`,
                    disclose: `sequenced`,
                    empathy: 60,
                    backup: 50,
                    defend: `eiethics`,
                    precedent: `fairtough`,
                    thirty: `concrete`,
                    courage: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rd = document.getElementById(`readInput`);
                const cl = document.getElementById(`clashInput`);
                const lk = document.getElementById(`linkInput`);
                if (rd) decisions.read = rd.value;
                if (cl) decisions.clash = cl.value;
                if (lk) decisions.link = parseInt(lk.value, 10);
                if (!Number.isFinite(decisions.link) || decisions.link < 0 || decisions.link > 100) {
                    warn(`warn_link_range`); return false;
                }
            } else if (round === 2) {
                const me = document.getElementById(`methodInput`);
                const ai = document.getElementById(`thirdAishaInput`);
                const op = document.getElementById(`optionsInput`);
                const pu = document.getElementById(`publicityInput`);
                if (me) decisions.method = me.value;
                if (ai) decisions.thirdAisha = ai.value;
                if (op) decisions.options = parseInt(op.value, 10);
                if (pu) decisions.publicity = parseInt(pu.value, 10);
                if (!Number.isFinite(decisions.options) || decisions.options < 0 || decisions.options > 6) {
                    warn(`warn_options_range`); return false;
                }
                if (!Number.isFinite(decisions.publicity) || decisions.publicity < 0 || decisions.publicity > 100) {
                    warn(`warn_publicity_range`); return false;
                }
            } else if (round === 3) {
                const to = document.getElementById(`tomInput`);
                const di = document.getElementById(`discloseInput`);
                const em = document.getElementById(`empathyInput`);
                const bk = document.getElementById(`backupInput`);
                if (to) decisions.tom = to.value;
                if (di) decisions.disclose = di.value;
                if (em) decisions.empathy = parseInt(em.value, 10);
                if (bk) decisions.backup = parseInt(bk.value, 10);
                if (!Number.isFinite(decisions.empathy) || decisions.empathy < 0 || decisions.empathy > 100) {
                    warn(`warn_empathy_range`); return false;
                }
                if (!Number.isFinite(decisions.backup) || decisions.backup < 0 || decisions.backup > 100) {
                    warn(`warn_backup_range`); return false;
                }
            } else if (round === 4) {
                const de = document.getElementById(`defendInput`);
                const pr = document.getElementById(`precedentInput`);
                const th = document.getElementById(`thirtyInput`);
                const co = document.getElementById(`courageInput`);
                if (de) decisions.defend = de.value;
                if (pr) decisions.precedent = pr.value;
                if (th) decisions.thirty = th.value;
                if (co) decisions.courage = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.courage) || decisions.courage < 0 || decisions.courage > 100) {
                    warn(`warn_courage_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // trust = the real KPI (how the 14 read this); ethics = Candour/Care/Courage alignment;
            // deadline = Thursday Aurora milestone safety; cred = legitimate authority vs "a stretch".
            let trustDelta = 0, ethicsDelta = 0, deadlineDelta = 0, credDelta = 0;
            // exposureDelta in £M: NEGATIVE reduces the value at risk.
            let exposureDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the people, not just the problem (Common Error 1: solving before reading).
                if (d.read === this.RIGHT_READ) {
                    trustDelta += 8; ethicsDelta += 6; credDelta += 6; coachKey = `coach_r1_read`;
                } else if (d.read === `decide`) {
                    trustDelta -= 8; ethicsDelta -= 4; credDelta -= 6; deadlineDelta += 2; coachKey = `coach_r1_decide`;
                } else if (d.read === `numbers`) {
                    trustDelta -= 6; ethicsDelta -= 6; credDelta -= 4; deadlineDelta += 2; coachKey = `coach_r1_numbers`;
                } else {
                    trustDelta -= 4; credDelta -= 8; coachKey = `coach_r1_escalate`;
                }

                // Name the genuine values clash in one sentence.
                if (d.clash === this.RIGHT_CLASH) {
                    ethicsDelta += 10; credDelta += 6;
                    if (d.read === this.RIGHT_READ) coachKey = `coach_r1_sharp`;
                } else if (d.clash === `deadline`) {
                    ethicsDelta -= 8; credDelta -= 2; coachKey = `coach_r1_notclash`;
                } else if (d.clash === `tomonly`) {
                    ethicsDelta -= 4; coachKey = `coach_r1_tomonly`;
                } else {
                    ethicsDelta -= 6; trustDelta -= 4; coachKey = `coach_r1_loyalty`;
                }

                // Treat the two dilemmas as one system (Common Error 5 / decision tree #6).
                if (d.link >= 60) { credDelta += 6; deadlineDelta += 4; }
                else if (d.link <= 25) { deadlineDelta -= 6; credDelta -= 4; coachKey = `coach_r1_independent`; }

                summaryKey = (d.read === this.RIGHT_READ && d.clash === this.RIGHT_CLASH) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Run the structured ethical decision method.
                switch (d.method) {
                    case `full`: ethicsDelta += 8; credDelta += 6; coachKey = `coach_r2_full`; break;
                    case `gut`: ethicsDelta -= 4; credDelta -= 6; coachKey = `coach_r2_gut`; break;
                    case `binary`: ethicsDelta -= 6; trustDelta -= 4; coachKey = `coach_r2_binary`; break;
                }

                // The Aisha route: third option vs complicity vs breaking a confidence (Common Error 3).
                switch (d.thirdAisha) {
                    case `thirdway`:
                        ethicsDelta += 14; trustDelta += 8; credDelta += 6;
                        coachKey = (d.method === `full`) ? `coach_r2_thirdway` : coachKey;
                        break;
                    case `conceal`:
                        // Complicity — deadline looks helped now, but Candour is breached and it unravels later.
                        ethicsDelta -= 14; credDelta -= 8; deadlineDelta += 4; ds.complicit = true;
                        coachKey = `coach_r2_conceal`;
                        break;
                    case `expose`:
                        // Honest to the firm but betrays Aisha's confidence — trust and integrity both bruised.
                        ethicsDelta += 2; trustDelta -= 10; coachKey = `coach_r2_expose`;
                        break;
                }

                // Genuine option generation (three or more breaks keep-or-replace).
                if (d.options >= 3) { ethicsDelta += 6; credDelta += 2; }
                else if (d.options <= 1) { ethicsDelta -= 6; coachKey = `coach_r2_fewoptions`; }

                // Publicity test ("could I defend this to all 14?").
                if (d.publicity >= 60) { trustDelta += 5; ethicsDelta += 3; }
                else if (d.publicity <= 25) { trustDelta -= 5; ethicsDelta -= 3; coachKey = `coach_r2_lowpublicity`; }

                summaryKey = (d.thirdAisha === this.RIGHT_AISHA && d.method === this.RIGHT_METHOD) ? `sum_r2_good`
                    : (d.thirdAisha === `conceal` ? `sum_r2_complicit` : `sum_r2_weak`);
            } else if (round === 3) {
                // The conversations — delivery creates or destroys value (Key Concept; Common Error 2).
                switch (d.tom) {
                    case `caretruth`: trustDelta += 10; ethicsDelta += 8; credDelta += 4; coachKey = `coach_r3_caretruth`; break;
                    case `blunt`:
                        // Candour without care — contagion attrition; the bigger £600k cost, not the £95k credit.
                        trustDelta -= 12; ethicsDelta -= 4; exposureDelta += 0.6; coachKey = `coach_r3_blunt`;
                        break;
                    case `avoid`: trustDelta -= 4; ethicsDelta -= 8; credDelta -= 6; coachKey = `coach_r3_avoid`; break;
                }

                // Disclosure sequence — confidence vs complicity, done in order, before Thursday.
                switch (d.disclose) {
                    case `sequenced`: ethicsDelta += 8; trustDelta += 6; deadlineDelta += 4; break;
                    case `ownerblind`: ethicsDelta -= 8; deadlineDelta -= 6; coachKey = `coach_r3_ownerblind`; break;
                    case `dumpall`: trustDelta -= 8; ethicsDelta -= 4; coachKey = `coach_r3_dumpall`; break;
                }

                // Empathy & self-regulation in the room.
                if (d.empathy >= 60) { trustDelta += 6; }
                else if (d.empathy <= 25) { trustDelta -= 6; ethicsDelta -= 2; coachKey = `coach_r3_lowempathy`; }

                // Contingency so the Tom fix is not built on a person who may resign Friday.
                if (d.backup >= 60) { deadlineDelta += 12; exposureDelta -= 1.6; }
                else if (d.backup >= 35) { deadlineDelta += 5; exposureDelta -= 0.6; }
                else { deadlineDelta -= 8; coachKey = `coach_r3_nobackup`; }

                summaryKey = (d.tom === this.RIGHT_TOM && d.disclose === this.RIGHT_DISCLOSE) ? `sum_r3_good`
                    : (d.tom === `blunt` ? `sum_r3_cruel` : `sum_r3_weak`);
            } else if (round === 4) {
                // Decide, defend & set the tone (Common Error 4 + precedent-setting).
                switch (d.defend) {
                    case `eiethics`: trustDelta += 6; ethicsDelta += 8; credDelta += 12; deadlineDelta += 2; coachKey = `coach_r4_eiethics`; break;
                    case `numbers`:
                        // Optimised only the visible £95k number — the expensive cheap-looking decision.
                        credDelta -= 4; trustDelta -= 8; ethicsDelta -= 6; exposureDelta += 0.3; coachKey = `coach_r4_numbers`;
                        break;
                    case `popularity`:
                        trustDelta -= 6; credDelta -= 10; ethicsDelta -= 6; deadlineDelta -= 6; coachKey = `coach_r4_popularity`;
                        break;
                }

                // Name the precedent — every decision is an act of culture-setting (decision tree #5).
                switch (d.precedent) {
                    case `fairtough`: trustDelta += 10; credDelta += 6; break;
                    case `authority`: trustDelta -= 6; credDelta += 2; coachKey = `coach_r4_authority`; break;
                    case `none`: trustDelta -= 8; credDelta -= 4; coachKey = `coach_r4_noprecedent`; break;
                }

                // First-30-days trust-building commitment — the lever on the 24% attrition figure.
                switch (d.thirty) {
                    case `concrete`: trustDelta += 10; credDelta += 4; exposureDelta -= 1.0; coachKey = (d.defend === this.RIGHT_DEFEND && d.precedent === this.RIGHT_PRECEDENT) ? `coach_r4_strong` : coachKey; break;
                    case `vague`: trustDelta -= 2; coachKey = `coach_r4_vague`; break;
                    case `nothing`: trustDelta -= 10; credDelta -= 4; coachKey = `coach_r4_nothing`; break;
                }

                // Courage — owning the trade-off rather than pretending it was cost-free.
                ethicsDelta += Math.round((d.courage - 60) / 8);

                summaryKey = (d.defend === this.RIGHT_DEFEND && d.precedent === this.RIGHT_PRECEDENT && d.thirty === this.RIGHT_THIRTY) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply KPI deltas with headroom (0–100).
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.ethics = Math.max(0, Math.min(100, ds.ethics + ethicsDelta));
            ds.deadline = Math.max(0, Math.min(100, ds.deadline + deadlineDelta));
            ds.cred = Math.max(0, Math.min(100, ds.cred + credDelta));

            // Value at risk: complicity keeps the renewal exposed; a safe deadline retires the credit risk.
            ds.exposure = Math.max(0, Math.min(this.MAX_EXPOSURE, ds.exposure + exposureDelta));
            if (round === this.ROUNDS.length) {
                // End-of-week reconciliation: a safe deadline + healthy trust retire most of the exposure;
                // an unsafe deadline keeps the renewal and credit on the table.
                if (ds.deadline >= 60 && ds.trust >= 55 && !ds.complicit) {
                    ds.exposure = Math.max(0, Math.min(ds.exposure, this.MAX_EXPOSURE - 5.7 - 0.095 - (ds.trust >= 65 ? 0.6 : 0)));
                }
                if (ds.deadline < 50) ds.deadlineMissed = true;
            }
            ds.exposure = Math.round(ds.exposure * 100) / 100;

            ds.trustHistory.push(Math.round(ds.trust));
            ds.ethicsHistory.push(Math.round(ds.ethics));
            ds.deadlineHistory.push(Math.round(ds.deadline));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                ethics: Math.round(ds.ethics),
                ethicsDelta: Math.round(ethicsDelta),
                deadline: Math.round(ds.deadline),
                deadlineDelta: Math.round(deadlineDelta),
                cred: Math.round(ds.cred),
                credDelta: Math.round(credDelta),
                exposure: ds.exposure,
                complicit: ds.complicit,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

