        // Shared composite (0-100). Written to domainState.performance.overallScore each period
        // for the reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            var trust = Math.round(ds.trust || 0);
            var ethics = Math.round(ds.ethics || 0);
            var deadline = Math.round(ds.deadline || 0);
            var cred = Math.round(ds.cred || 0);
            return Math.round(trust * 0.34 + ethics * 0.30 + deadline * 0.18 + cred * 0.18);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const trust = Math.round(ds.trust);
            const ethics = Math.round(ds.ethics);
            const deadline = Math.round(ds.deadline);
            const cred = Math.round(ds.cred);

            const deadlineSafe = deadline >= 60;
            const ledWell = trust >= 62 && ethics >= 62 && cred >= 58;
            const complicit = ds.complicit;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_stretch`;
            if (ledWell && deadlineSafe && !complicit && composite >= 72) performanceKey = `grade_leader`;
            else if (ledWell && deadlineSafe && !complicit) performanceKey = `grade_ownedtradeoff`;
            else if (complicit) performanceKey = `grade_complicit`;
            else if (deadlineSafe && trust < 45) performanceKey = `grade_lostteam`;
            else if (composite >= 55) performanceKey = `grade_defensible`;
            const performance = T(performanceKey);

            const insights = [];
            if (ledWell && deadlineSafe && !complicit) insights.push(window.mySimulation.t(`insight_leader`));
            else if (complicit) insights.push(window.mySimulation.t(`insight_complicit`));
            else if (deadlineSafe && trust < 45) insights.push(window.mySimulation.t(`insight_lostteam`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (trust < 45) insights.push(window.mySimulation.t(`insight_lowtrust`));
            if (ethics < 45) insights.push(window.mySimulation.t(`insight_lowethics`));
            if (!deadlineSafe) insights.push(window.mySimulation.t(`insight_milestone`));
            if (ledWell && deadlineSafe && !complicit && cred >= 65) insights.push(window.mySimulation.t(`insight_culture`));

            return {
                trust: trust,
                ethics: ethics,
                deadline: deadline,
                cred: cred,
                exposure: ds.exposure,
                complicit: complicit,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                led: (ledWell && deadlineSafe && !complicit),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var led = !!s.led;
            var badge = led
                ? '<span class="mdilemma-cm-badge mdilemma-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="mdilemma-cm-badge mdilemma-cm-no">' + T('cm_missed') + '</span>';
            var compBadge = s.complicit
                ? '<span class="mdilemma-cm-badge mdilemma-cm-warn">' + T('cm_complicit_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="mdilemma-cm-metric"><span class="mdilemma-cm-mv">' + Math.round(s.trust || 0) + '</span><span class="mdilemma-cm-ml">' + T('cm_m_trust') + '</span></div>'
                + '<div class="mdilemma-cm-metric"><span class="mdilemma-cm-mv">' + Math.round(s.ethics || 0) + '</span><span class="mdilemma-cm-ml">' + T('cm_m_ethics') + '</span></div>'
                + '<div class="mdilemma-cm-metric"><span class="mdilemma-cm-mv">' + Math.round(s.deadline || 0) + '</span><span class="mdilemma-cm-ml">' + T('cm_m_deadline') + '</span></div>'
                + '<div class="mdilemma-cm-metric"><span class="mdilemma-cm-mv">' + Math.round(s.cred || 0) + '</span><span class="mdilemma-cm-ml">' + T('cm_m_cred') + '</span></div>';
            return ''
                + '<div class="mdilemma-completion">'
                +   '<div class="mdilemma-cm-head">'
                +     '<div class="mdilemma-cm-score">' + score + '<span class="mdilemma-cm-score-max">/100</span></div>'
                +     '<div class="mdilemma-cm-grade">' + grade + ' ' + badge + compBadge + '</div>'
                +   '</div>'
                +   '<div class="mdilemma-cm-metrics">' + metrics + '</div>'
                +   '<div class="mdilemma-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="mdilemma-cm-insights">' + items + '</ul>'
                + '</div>';
        }

